@app.post("/mona/shutdown", dependencies=[Depends(require_auth)])
async def shutdown():
    server = getattr(app.state, "mona_server", None)
    if server is None:
        raise HTTPException(status_code=503, detail="Host server lifecycle unavailable")
    server.should_exit = True
    return {"stopping": True}

